import java.util.*;

public class Main {
    int[] nextLargerNodes(int[] values) {
        int[] result = new int[values.length];
        for (int i = 0; i < values.length; i++) {
            for (int j = i + 1; j < values.length; j++) {                              // scan forward for the FIRST strictly larger value
                if (values[j] > values[i]) {
                    result[i] = values[j];
                    break;
                }
            }
        }
        return result;
    }

    public static void main(String[] args) {
        Main solution = new Main();
        int[] values = {2, 7, 4, 3, 5};
        System.out.println(Arrays.toString(solution.nextLargerNodes(values)));
    }
}

