import java.util.*;

public class Main {
    int[] nextLargerNodes(int[] values) {
        int[] result = new int[values.length];
        Deque<Integer> stack = new ArrayDeque<>();                                    // a monotonic DECREASING stack of indices still awaiting their answer
        for (int i = 0; i < values.length; i++) {
            while (!stack.isEmpty() && values[stack.peek()] < values[i]) {              // values[i] is the first bigger value for everything smaller on top
                result[stack.pop()] = values[i];
            }
            stack.push(i);
        }
        return result;                                                                   // anything left on the stack never found a bigger value (stays 0)
    }

    public static void main(String[] args) {
        Main solution = new Main();
        int[] values = {2, 7, 4, 3, 5};
        System.out.println(Arrays.toString(solution.nextLargerNodes(values)));
    }
}

